head.script:
scwin.onpageload = function() {
    //		dataList1.setJSON([{"chk":"","col1":"1"},{"chk":"","col1":"1"},{"chk":"","col1":"2"},{"chk":"","col1":"3"},{"chk":"","col1":"3"},{"chk":"","col1":"4"},{"chk":"","col1":"5"},{"chk":"","col1":"6"},{"chk":"","col1":"6"},{"chk":"","col1":"7"},{"chk":"","col1":"8"}]);
};
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('gridView1_column5_filter').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getDomById($p.id+'gridView1_customFilter_scrollView').style.height != ''", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
